atoms.extended_explanation:
# ═══════════════════════════════════════════════════════════════════
version: 1
project: ESTATE-2026-REVENUE
baseline: 2026-07-21
window: {start: "2026-07-21", end: "2026-07-26"}
globals:
memory:
root: 00-MEMORY
cli: "python3 00-MEMORY/memory_manager.py"
rule_zero: "task chiuso -> checkpoint; decisione -> decision; fallimento -> error"
eod_hook: "checkpoint giornaliero + metriche h19:00 (WF-MEM-EOD)"
perf_hook: "OGNI azione chiusa -> PERF record (P-LOOP T1) -> analisi/dispatch/conferma (WF-PERF-LOOP)"
constraints:
single_opus_swarm: true          # CP-20260711-002 · ADR-EST-004
swarm_queue: [S1, S2, S6, S5]    # priorità coda
secrets: {FLIKI_API_KEY: ".env locale (gitignored) — MAI nei file/prompt"}
dod_frozen: true                 # ADR-EST-005
decision_policy: default_plus_veto # ADR-EST-006: scade il veto -> default ATTIVO
decisions:                            # mirror di 00-MEMORY/decisions (source of truth)
- {id: DEC-EST-001, topic: "prezzo Manuale (B-003)", default: "EUR 67 lancio / EUR 97 listino", veto_deadline: "2026-07-21T20:00", blocks: [S2, S3, S4]}
- {id: DEC-EST-002, topic: "nome prodotto S6", default: "Preventa", veto_deadline: "2026-07-22T12:00", blocks: [S6]}
- {id: DEC-EST-004, topic: "nicchia YT #1", default: "AI/Claude IT", veto_deadline: "2026-07-24T18:00", blocks: [S5]}
workflows:
WF-MASTER:
type: orchestrator
owner: chief-forge
schedule: continuous
loop:
- "mattina: leggi dashboard + gate del giorno (07-CONTROL/DASHBOARD-E-RETRO.md)"
- "esegui corsie Max/Gael/Claude da PLANNING-P7 §2"
- "h19:00 -> WF-MEM-EOD"
- "gate scaduto -> marcare 🟢/🔴 e applicare kill criteria (PLANNING-P5 §2)"
gates: [Gate-DEC, Gate-FUNNEL, Gate-CONTATTI, Gate-S4, Gate-S5, Gate-REV]
WF-S1-CONCESSIONARI:
owner: Max; support: [claude, chief-forge]; window: 21→26/07
doD: ">=1 anticipo incassato (setup o canone)"
steps:
- {id: s1.1, who: Max, task: "lista 7 lead (nome/stato/canale/ultimo contatto)", due: "2026-07-21"}
- {id: s1.2, who: claude, task: "script WA msg1-2-3 + argomentario obiezioni", due: "2026-07-21", skill: [beast-preventivi, A8-closing]}
- {id: s1.3, who: Max, task: "contatti WA-first: 2 (21/07), 3 (22/07), 2 + follow-up (23/07)", gate: Gate-CONTATTI}
- {id: s1.4, who: Max, task: "chiusura: link pagamento setup contrattualizzato", due: "2026-07-25"}
- {id: s1.5, who: gael, task: "clone app via /nuovo-concessionario il giorno della firma", on: chiusura}
offer:
name: "Partenza Anticipata Luglio"
terms: ["setup -30% OPPURE primo mese gratis", "attivazione entro 31/07", "prezzo 2026 bloccato", "onboarding entro 20/08"]
angle: "A settembre sei GIA' operativo. Gli altri staranno installando."
fallback: {max_unavailable: "chiusura asincrona via msg-3 binario (P4 §2)"}
memory: {on_close: "metric --name s1_anticipi_chiusi --value <n>; metric --name s1_incasso_eur --value <eur>"}
WF-S2-MANUALE:
owner: chief-forge (gael); copy: claude; window: 21→26/07
depends: [DEC-EST-001]
doD: "1 landing + checkout test €1 OK + 3 email caricate (STOP — vendibile, non perfetto)"
steps:
- {id: s2.1, who: sistema, task: "DEC-001 ATTIVA entro veto 21/07 h20:00"}
- {id: s2.2, who: claude, task: "copy landing + 3 email (cro-copy-architect APSOC)", due: "2026-07-21 sera"}
- {id: s2.3, who: gael, task: "landing empire-premium-style + checkout live", due: "2026-07-22", gate: Gate-FUNNEL}
- {id: s2.4, who: gael, task: "lead-magnet Parte 1 (cap.1-3) come free download", due: "2026-07-22"}
- {id: s2.5, who: Max, task: "push su canali caldi (post/storie/contatti diretti)", due: "2026-07-23→26"}
checkout_ladder: [stripe_payment_link, gumroad, paypal_me, bonifico_typeform]
pricing: {launch: 67, list: 97, bump: "+EUR 27 pack template", currency: EUR}
memory: {on_sale: "metric --name s2_vendite_manuale --value <n>"}
WF-S3-PAGINE:
owner: gael; window: 22→26/07
doD: "crea.illtuo_impero riparte con bio→funnel + >=3 caroselli pubblicati"
steps:
- {id: s3.1, who: gael, task: "AUDIT pagine (follower/ultimo post/accessi-2FA/bio)", due: "2026-07-21", output: "07-CONTROL/AUDIT-PAGINE-20260721.md"}
- {id: s3.2, who: gael, task: "bio + link in bio -> funnel S2", due: "2026-07-22"}
- {id: s3.3, who: gael, task: "batch 7 caroselli via carousel-factory (1 run)", due: "2026-07-23"}
- {id: s3.4, who: sistema, task: "pubblicazione 1/giorno (Meta Graph API -> Buffer -> manuale)"}
rules: ["rampa anti-ban: max 1 post/giorno/pagina", "contenuti dal motore esistente, zero restyle (ADR-EST-002)"]
memory: {daily: "metric --name s3_caroselli_pubblicati --value <n>"}
WF-S4-MENTALITA:
owner: gael; window: 23→25/07; hard_rule: "condizione Max F-07: SOLO se automazione 100%, altrimenti STANDBY"
doD_gate: "E2E: batch -> QA auto -> scheduler -> report. Test run dimostrabile"
steps:
- {id: s4.1, who: gael, task: "wrap carousel-factory brand mentalita-brutale (config esistente)", due: "2026-07-23"}
- {id: s4.2, who: gael, task: "gate QA automatico su regole copy", due: "2026-07-24"}
- {id: s4.3, who: gael, task: "scheduler pubblicazione (Meta Graph API/Buffer)", due: "2026-07-24"}
- {id: s4.4, who: gael, task: "report engagement settimanale automatico", due: "2026-07-24", gate: Gate-S4}
monetization: "link in bio -> lead-magnet -> S2 (niente long-term-only)"
no_go: "dichiarare STANDBY con error --wf WF-S4 e archiviare a settimana prox"
WF-S5-YOUTUBE:
owner: youtube-dept; window: 24→25/07; depends: [DEC-EST-004, Gate-S5]
doD: "1 video renderizzato + pubblicato + trace P12 + checkpoint (basta)"
stages:                              # pipeline 9-stage Empire Studio (dossier S5)
- {stage: 0, name: memory-bootstrap, agent: strategy-dept}
- {stage: 1, name: ingestion, agent: yt-channel-ingester / video-single-ingester}
- {stage: 2, name: frame-extraction, tools: [ffmpeg]}
- {stage: 3, name: visione-reale, agent: video-watcher}
- {stage: 4, name: knowledge-atoms, agent: knowledge-extractor, trace: P12}
- {stage: 5, name: verifica, agents: [visual-verifier, compliance-auditor]}
- {stage: 6, name: forge-render, agents: [content-forge-invoker, yt-fliki-renderer]}
- {stage: 7, name: publish, agents: [wiki-writer, yt-seo-publisher]}
- {stage: 8, name: improve, agent: update-proposer -> ReasoningBank}
- {stage: 9, name: memory-close, agent: checkpoint-manager}
render_ladder: [fliki_api, "script+stock+tts+ffmpeg", deferred]
revenue_path: "lead-gen via link Manuale in descrizione (sempre), AdSense/compounding dopo"
rules: ["chiave Fliki solo .env", "1 video solo questa settimana", "ogni run -> memory_manager checkpoint"]
WF-S6-REBRAND-PROMO:
owner: chief-forge; decisions: [DEC-EST-002]; window: 22→26/07
doD: "1 landing Preventa + 1 demo video <=2min + 1 case study PDF"
steps:
- {id: s6.1, who: Max, task: "veto/ok nome (30 sec)", due: "2026-07-22 h12:00"}
- {id: s6.2, who: gael, task: "verifica dominio/handle DOPO la scelta", due: "2026-07-22"}
- {id: s6.3, who: claude, task: "case study Novacar (case-study-forge: tempi/PDF/consegna reali)", due: "2026-07-23"}
- {id: s6.4, who: gael, task: "landing empire-premium-style + demo video 2min", due: "2026-07-24"}
- {id: s6.5, who: A1, task: "scrape dealer IT import-DE (mobile.de) -> lista lead", due: "2026-07-25"}
- {id: s6.6, who: A2, task: "runtime outreach con case study (sequenza email)", due: "2026-07-26"}
testimonial: "i 7 di S1 chiusi diventano i primi casi pubblici del rebrand"
WF-MEM-EOD:
owner: memory-architect; schedule: "daily 19:00"
steps: ["raccolta metriche del giorno (tracker P6)", "aggiornamento dashboard gate", "checkpoint EOD", "segnalazione slittamenti -> error"]
WF-MEM-RETRO:
owner: strategy-dept; schedule: "2026-07-26"
steps: ["status memoria + numeri veri", "per stream: ✅/⚠️/❌ + causa radice", "pattern vincenti -> reasoning-bank", "sync note fisse -> second-brain", "CP RETRO-20260726"]
WF-PERF-LOOP:
owner: performance-cell (memory-dir, sponsor TRUTH-CMD); trigger: "post-task di OGNI workflow, ogni singola volta"
spec: 03-WORKFLOWS/WF-PERF-LOOP.md; agents: 04-AGENTS/PERFORMANCE-CELL.md
cycle: [T0 azione chiusa, T1 capture PERF record (file write, fuori quota), T2 analisi 5D entro EOD (debug/soluzione/struttura/scope/efficiency), T3 synthesize -> ReasoningBank DRAFT, T4 dispatch TIP/RULE-NOTE/MUTATION-PROP, T5 confirm alla prossima PERF: confirmed->pattern ufficiale | recurred->mutation obbligatoria]
storage: [00-MEMORY/performances, 00-MEMORY/feedback]
rules: ["non blocca mai (non e' un verificatore)", "anti-nagging: stesso TIP non ripetuto entro 3 task", "FB senza conferma >5 task -> riesumato in EOD-SYNC", "solo pattern confirmed precaricati dal pre_task hook"]
traceability: {spec: "ogni WF cita DEC-EST-xxx e CP-xxx che lo attivano (P12)"}
